/* Offline compiler: bundled generic hiding selectors to two static stylesheets. */
'use strict';
const fs = require('node:fs');
require('../src/blocking/cosmetic.js');
const { safeSelector, hidingCss, GENERIC_OFF_ATTRIBUTE } = globalThis.BlockAdsCosmetic;

// Some selectors contain non-ASCII text; @charset must be the file's first bytes.
const HEADER = `@charset "UTF-8";
/* Generated by scripts/community-list-tools.ps1 from the bundled community lists; rebuild instead of editing.
   A frame whose root element has ${GENERIC_OFF_ATTRIBUTE} shows these elements again. */\n`;
const LEGACY_PSEUDO_ELEMENT = /^:(?:before|after|first-line|first-letter)(?![\w-])/i;

// Adds `condition` to the subject of every top-level selector: before its first
// pseudo-element, otherwise at the end. Returns null when the result could match
// more than the input could, such as `a >` (invalid) becoming `a >:not(...)`.
function scope(selector, condition) {
  const parts = [];
  let start = 0, depth = 0, square = 0, quote = '', pseudo = -1;
  for (let i = 0; i < selector.length; i++) {
    const char = selector[i];
    if (char === '\\') { i++; continue; }
    if (quote) { if (char === quote) quote = ''; continue; }
    if (char === '"' || char === "'") quote = char;
    else if (char === '[') square++;
    else if (char === ']') square--;
    else if (square) continue;
    else if (char === '(') depth++;
    else if (char === ')') depth--;
    else if (depth) continue;
    else if (char === ',') { parts.push([start, i, pseudo]); start = i + 1; pseudo = -1; }
    else if (char === ':' && pseudo < 0 && (selector[i + 1] === ':' || LEGACY_PSEUDO_ELEMENT.test(selector.slice(i)))) pseudo = i;
  }
  parts.push([start, selector.length, pseudo]);
  const scoped = [];
  for (const [from, to, at] of parts) {
    const subject = selector.slice(from, at < 0 ? to : at);
    if (at < 0) {
      const text = subject.trim();
      // The last character must end a simple selector: a name, `*`, `]`, `)` or
      // an escaped character (preceded by an odd number of backslashes).
      let slashes = 0;
      for (let j = text.length - 2; j >= 0 && text[j] === '\\'; j--) slashes++;
      if (!text || !(/[\w\u0080-￿*\])-]$/.test(text) || slashes % 2)) return null;
      scoped.push(text + condition);
    } else scoped.push((subject + condition + selector.slice(at, to)).trim());
  }
  return scoped.join(', ');
}

// True for one complex selector that Chrome 121+ and Firefox 128+ both parse:
// type, universal, id, class and attribute selectors, structural pseudo-classes
// and :not(), joined by combinators, without escapes or pseudo-elements. These
// share a rule; anything else gets its own, so a selector one browser rejects
// cannot void its neighbours.
const IDENT = /^-?[_a-zA-Z\u0080-￿][\w\u0080-￿-]*/;
const PLAIN = new Set(['first-child', 'last-child', 'only-child', 'first-of-type', 'last-of-type', 'only-of-type', 'empty', 'root']);
const NTH = new Set(['nth-child', 'nth-last-child', 'nth-of-type', 'nth-last-of-type']);
function groupable(selector) {
  let i = 0;
  const text = selector;
  const space = () => { const from = i; while (/[ \t\n\r\f]/.test(text[i] || '')) i++; return i > from; };
  const take = pattern => { const match = pattern.exec(text.slice(i)); if (match) i += match[0].length; return Boolean(match); };
  const string = () => {
    const quote = text[i];
    if (quote !== '"' && quote !== "'") return false;
    const end = text.indexOf(quote, i + 1);
    if (end < 0 || /[\\\n\r\f]/.test(text.slice(i + 1, end))) return false;
    i = end + 1;
    return true;
  };
  const attribute = () => {
    space();
    if (!take(IDENT)) return false;
    space();
    if (take(/^[~|^$*]?=/)) {
      space();
      if (!string() && !take(IDENT)) return false;
      space();
      if (take(/^[iI](?![\w-])/)) space();
    }
    if (text[i] !== ']') return false;
    i++;
    return true;
  };
  const compound = depth => {
    let parts = 0;
    if (text[i] === '*') { i++; parts++; } else if (take(IDENT)) parts++;
    for (;;) {
      const char = text[i];
      if (char === '#' || char === '.') { i++; if (!take(IDENT)) return false; }
      else if (char === '[') { i++; if (!attribute()) return false; }
      else if (char === ':' && text[i + 1] !== ':') {
        i++;
        const name = /^[a-zA-Z-]+/.exec(text.slice(i))?.[0].toLowerCase();
        if (!name) return false;
        i += name.length;
        if (text[i] === '(') {
          i++;
          space();
          if (name === 'not' && depth < 2) { if (!list(depth + 1)) return false; }
          else if (NTH.has(name)) { if (!take(/^(?:odd|even|[+-]?\d*n(?:\s*[+-]\s*\d+)?|[+-]?\d+)/i)) return false; }
          else return false;
          space();
          if (text[i] !== ')') return false;
          i++;
        } else if (!PLAIN.has(name)) return false;
      } else break;
      parts++;
    }
    return parts > 0;
  };
  const complex = depth => {
    if (!compound(depth)) return false;
    for (;;) {
      const spaced = space();
      if (/[>+~]/.test(text[i] || '')) { i++; space(); if (!compound(depth)) return false; }
      else if (spaced && /[\w\u0080-￿*#.[:-]/.test(text[i] || '')) { if (!compound(depth)) return false; }
      else return true;
    }
  };
  const list = depth => {
    for (;;) {
      space();
      if (!complex(depth)) return false;
      space();
      if (text[i] !== ',') return true;
      i++;
    }
  };
  space();
  if (!complex(0)) return false;
  space();
  return i === text.length;
}

function stylesheet(selectors, condition) {
  const grouped = [], single = [];
  for (const selector of selectors) (groupable(selector) ? grouped : single).push(scope(selector, condition));
  return (HEADER + hidingCss(grouped) + single.map(selector => `${selector} { display: none !important; }\n`).join('')).trimEnd();
}

// `cosmetic`: { generic, allow, exceptions }, where exceptions are the scoped and
// procedural exception rules ({ include, exclude, selector }) of the bundle.
function compile(cosmetic, { attribute = GENERIC_OFF_ATTRIBUTE } = {}) {
  if (!cosmetic || !Array.isArray(cosmetic.generic) || !cosmetic.allow || typeof cosmetic.allow !== 'object' || !Array.isArray(cosmetic.exceptions)) {
    throw new Error('Invalid generic stylesheet input.');
  }
  const condition = `:not(:where([${attribute}] *))`;
  const never = new Set(cosmetic.allow['*'] || []), perFrameOnly = new Set(), sitesBySelector = new Map();
  const except = (selector, sites) => {
    if (!sitesBySelector.has(selector)) sitesBySelector.set(selector, new Set());
    for (const site of sites) sitesBySelector.get(selector).add(site);
  };
  for (const [site, selectors] of Object.entries(cosmetic.allow)) if (site !== '*') for (const selector of selectors) except(selector, [site]);
  for (const rule of cosmetic.exceptions) {
    if (!rule || typeof rule.selector !== 'string' || !Array.isArray(rule.include) || !Array.isArray(rule.exclude)) throw new Error('Invalid exception rule.');
    // Without a positive site, an exception applies everywhere except its exclusions.
    if (rule.include.length) except(rule.selector, rule.include);
    else if (rule.exclude.length) perFrameOnly.add(rule.selector);
    else never.add(rule.selector);
  }
  const base = [], excepted = [], perFrame = [], exceptedSites = new Set();
  for (const selector of new Set(cosmetic.generic)) {
    if (never.has(selector)) continue;
    let safe = !perFrameOnly.has(selector);
    try { safeSelector(selector); } catch { safe = false; }
    if (safe && scope(selector, condition) === null) safe = false;
    if (!safe) perFrame.push(selector);
    else if (sitesBySelector.has(selector)) {
      excepted.push(selector);
      for (const site of sitesBySelector.get(selector)) exceptedSites.add(site);
    } else base.push(selector);
  }
  return {
    stylesheets: { base: stylesheet(base, condition), excepted: stylesheet(excepted, condition) },
    genericStatic: { excepted, exceptedSites: [...exceptedSites].sort(), perFrame },
    counts: { base: base.length, excepted: excepted.length, exceptedSites: exceptedSites.size, perFrame: perFrame.length,
      separateRules: [...base, ...excepted].filter(selector => !groupable(selector)).length }
  };
}

module.exports = { compile, scope, groupable };

if (require.main === module) {
  try {
    const chunks = [], buffer = Buffer.alloc(65536);
    let size = 0, read;
    while ((read = fs.readSync(0, buffer, 0, buffer.length, null))) {
      size += read;
      if (size > 8 * 1024 * 1024) throw new Error('Generic stylesheet input exceeds 8 MiB.');
      chunks.push(Buffer.from(buffer.subarray(0, read)));
    }
    const input = JSON.parse(new TextDecoder('utf-8', { fatal: true }).decode(Buffer.concat(chunks, size)));
    process.stdout.write(JSON.stringify(compile(input)));
  } catch (error) {
    process.stderr.write(`Generic stylesheet compilation failed: ${error.message}\n`);
    process.exitCode = 1;
  }
}
